files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

html {
  height: 100vh;
}

body {
  --main-text-color: #152028;
  --main-background-color: #fff;

  display: grid;
  place-items: center;
  min-height: 100%;
  color: var(--main-text-color);
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: var(--main-background-color);
}

@media (prefers-color-scheme: dark) {
  body {
    --main-text-color: #ffffff;
    --main-background-color: #152028;
  }
}

@media (prefers-color-scheme: light) {
  body {
    --main-text-color: #152028;
    --main-background-color: #ffffff;
  }
}

body:has(.theme-toggler__control_type_light:checked) {
  --main-text-color: #152028;
  --main-background-color: #fff;
}

body:has(.theme-toggler__control_type_dark:checked) {
  --main-text-color: #fff;
  --main-background-color: #152028;
}

.title {
  font-weight: 800;
  font-size: 45px;
  text-align: center;
  text-transform: uppercase;
}

.something {
  width: max(250px, 50vw);
  height: max(250px, 50vw);
  background-image: url(./images/tsss.svg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
}

.theme-toggler {
  display: flex;
}

.theme-toggler__item {
  position: relative;
  box-sizing: border-box;
  min-width: 125px;
  border: 1px solid var(--main-text-color);
  padding: 5px 20px;
  color: var(--main-text-color);
  font-family: inherit;
  font-weight: 400;
  font-size: inherit;
  text-align: center;
  text-transform: uppercase;
  cursor: pointer;
}

.theme-toggler__control {
  position: absolute;
  -webkit-appearance: none;
  appearance: none;
}

.theme-toggler__item:has(.theme-toggler__control:checked) {
  color: var(--main-background-color);
  font-weight: 800;
  background-color: var(--main-text-color);
}
